<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<div class="space-y-6"><div><h1 class="text-3xl font-bold">EPG</h1><p class="text-slate-400">Fuentes XMLTV para la guía electrónica de programación.</p></div><section class="bg-slate-900 border border-slate-800 rounded-xl p-5"><h2 class="text-xl font-bold">Agregar fuente XMLTV</h2><form method="post" action="/epg" class="grid md:grid-cols-5 gap-3 mt-4"><?=$csrf->field()?><input required name="name" placeholder="Nombre" class="bg-slate-800 p-2 rounded"><input required type="url" name="source_url" placeholder="https://proveedor/guide.xml" class="md:col-span-2 bg-slate-800 p-2 rounded"><input required name="timezone" value="UTC" placeholder="America/New_York" class="bg-slate-800 p-2 rounded"><input type="number" min="15" max="10080" name="refresh_minutes" value="360" class="bg-slate-800 p-2 rounded"><label><input type="checkbox" name="active" checked> Activa</label><button class="md:col-start-5 bg-cyan-700 p-2 rounded">Agregar EPG</button></form></section><section class="grid lg:grid-cols-2 gap-4"><?php foreach($sources as $s):?><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><div class="flex justify-between"><div><h2 class="text-xl font-bold"><?=$e($s['name'])?></h2><p class="text-xs text-slate-500 break-all"><?=$e($s['source_url'])?></p></div><span class="<?=$s['last_status']==='completed'?'text-emerald-400':($s['last_status']==='failed'?'text-red-400':'text-amber-400')?>"><?=$e($s['last_status'])?></span></div><div class="grid grid-cols-3 gap-2 mt-4 text-center"><div class="bg-slate-800 p-2 rounded"><strong><?=number_format($s['channels'])?></strong><div class="text-xs text-slate-500">canales</div></div><div class="bg-slate-800 p-2 rounded"><strong><?=number_format($s['programmes'])?></strong><div class="text-xs text-slate-500">programas</div></div><div class="bg-slate-800 p-2 rounded"><strong><?=$s['refresh_minutes']?></strong><div class="text-xs text-slate-500">minutos</div></div></div><div class="text-xs text-slate-400 mt-3">Última importación: <?=$e($s['last_import_at']??'Nunca')?> · <?=$e($s['timezone'])?></div><?php if($s['last_error']):?><div class="mt-2 text-xs text-red-400"><?=$e($s['last_error'])?></div><?php endif?><form method="post" action="/epg/run" class="mt-4"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$s['id']?>"><button class="bg-emerald-700 px-4 py-2 rounded">Actualizar ahora</button></form></article><?php endforeach?><?php if(!$sources):?><p class="text-slate-500">No hay fuentes EPG configuradas.</p><?php endif?></section></div>
